<?php require_once __DIR__.'/includes/catalog.php'; $category=$category??'new'; $label=$category==='new'?'New iPhones':'Refurbished iPhones'; $all=array_filter(products(),fn($p)=>$p['category']===$category); $q=trim((string)($_GET['q']??'')); if($q!=='')$all=array_filter($all,fn($p)=>stripos($p['name'].' '.$p['condition'].' '.implode(' ',$p['storage']),$q)!==false);$storage=trim((string)($_GET['storage']??''));if($storage!=='')$all=array_filter($all,fn($p)=>in_array($storage,$p['storage'],true));$max=(float)($_GET['max_price']??0);if($max>0)$all=array_filter($all,fn($p)=>$p['price']<=$max);$sort=$_GET['sort']??'featured';if($sort==='low')usort($all,fn($a,$b)=>$a['price']<=>$b['price']);elseif($sort==='high')usort($all,fn($a,$b)=>$b['price']<=>$a['price']);elseif($sort==='discount')usort($all,fn($a,$b)=>$b['discount']<=>$a['discount']);$meta=page_meta($label.' — Save '.($category==='new'?10:30).'%');require __DIR__.'/includes/header.php'; ?>
<section class="page-hero"><p class="eyebrow"><?=e(strtoupper($label))?></p><h1 class="page-title"><?=e($label)?> — Save <?=$category==='new'?10:30?>%</h1><p class="muted">Clear pricing and selected configurations. Product availability shown here is demo data and must be verified before launch.</p></section><section class="wrap"><form class="filters"><input name="q" value="<?=e($q)?>" placeholder="Search model or storage" aria-label="Search products"><select name="storage"><option value="">Any storage</option><?php foreach(['64GB','128GB','256GB','512GB','1TB'] as $s):?><option <?=$storage===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><input name="max_price" type="number" min="0" step="1" value="<?=e($_GET['max_price']??'')?>" placeholder="Max price"><select name="sort"><option value="featured">Featured</option><option value="low" <?=$sort==='low'?'selected':''?>>Price: low to high</option><option value="high" <?=$sort==='high'?'selected':''?>>Price: high to low</option><option value="discount" <?=$sort==='discount'?'selected':''?>>Discount</option></select><button class="button button-dark">Search</button></form><?php if($all)product_grid(array_values($all));else echo '<p>No matching iPhones. Try another search.</p>';?></section><?php require __DIR__.'/includes/footer.php'; ?>
